{"slice":{"slice_id":"s_distribue","introduces":[{"id":"eq4","type":"math","content":"3x - 2 = 2x + 12","parts":[{"id":"gauche","text":"3x - 2"},{"id":"eg","text":"="},{"id":"droite","text":"2x + 12"}]},{"id":"dist","type":"text","content":"2 × x = 2x   ;   2 × 6 = 12","layout":{"next_to":"eq4","direction":"right","gap":"md"}}],"beats":[{"id":"developpe","say":"Pour l'instant, on distribue le deux : deux fois x donne deux x, et deux fois six donne douze.","cues":[{"id":"c_distribue","text":"on distribue le deux"},{"id":"c_douze","text":"deux fois six donne douze"}],"do":[{"id":"t2","verb":"transform","source":"eq3","target":"eq4","at":"cue:c_distribue"},{"id":"s_dist","verb":"show","target":"dist","at":"cue:c_douze"}],"pause_after":"normal"}]}}
{"slice":{"slice_id":"s_resout","introduces":[{"id":"eq5","type":"math","content":"3x - 2x - 2 = 2x + 12 - 2x"},{"id":"eq6","type":"math","content":"x - 2 = 12"},{"id":"eq7","type":"math","content":"x = 14"}],"beats":[{"id":"regroupe","say":"On regroupe les x du côté où le coefficient reste positif : on enlève deux x des deux côtés.","cues":[{"id":"c_regroupe","text":"on enlève deux x"},{"id":"c_cotes","text":"des deux côtés"}],"do":[{"id":"t3","verb":"transform","source":"eq4","target":"eq5","at":"cue:c_regroupe"}]},{"id":"simplifie","say":"Les deux x s'annulent à droite : il reste x moins deux égale douze.","cues":[{"id":"c_annulent","text":"s'annulent à droite"},{"id":"c_reste","text":"x moins deux égale douze"}],"do":[{"id":"t4","verb":"transform","source":"eq5","target":"eq6","at":"cue:c_reste"}]},{"id":"isole","say":"On ajoute deux des deux côtés pour isoler x : x égale quatorze.","cues":[{"id":"c_ajoute","text":"ajoute deux"},{"id":"c_quatorze","text":"x égale quatorze"}],"do":[{"id":"t5","verb":"transform","source":"eq6","target":"eq7","at":"cue:c_ajoute"},{"id":"h_x","verb":"highlight","target":"eq7","role":"result","at":"cue:c_quatorze"}],"pause_after":"normal"}]}}
